    -- Configuration bits assignment
    -- Hard-wired value for k_gbl is now done inside the pciexp_top_hip module
    --assign k_gbl[15:0]           = {4'b1111, 1'b0, out_hip_ctrl_1[10], 1'b1, 1'b1, 6'b000000,out_hip_ctrl_1[1:0]}; 	// 
    -- k_gbl[15:12]=1111 type of core controlled by mode[1:0] signal for RP, EP shared silicon
    -- k_gbl[11]=0 if core is instantiated
    -- k_gbl[10]=0 cut-through mode disabled; 1 cut-through mode enabled
    -- k_gbl[9]: 1: slot reg implemented (harden to 1)
    -- k_gbl[8]: 1: 250Mhz; 0 125Mhz  (harden to 1)
    -- k_gbl[7:2]=000000 to disable VC7 to VC2
    -- k_gbl[0] = PCIe 1.1a (1) or PCie 1.0 (0)
    --assign k_gbl[31:16]          = {4'b0000, out_hip_ctrl_2[11],1'b1, 1'b0, 1'b0, out_hip_ctrl_2[7], 7'b0000000};     	// 
