    -- k_gbl[27]=0 rx buffer date checking disabled; 1: rx buffer date checking enabled
    -- k_gbl[26]=1 re-ordering enabled in RX
    -- k_gbl[25]=0 to indicate of separated RX buffers
    -- k_gbl[24]: reserved
    -- k_gbl[23]: CDC enable
    -- k_gbl[22:16]: 0000000: single function enabled
    k_gbl(15 DOWNTO 0) <= out_hip_ctrl_1;
    k_gbl(31 DOWNTO 16) <= out_hip_ctrl_2;
    k_gbl(47 DOWNTO 32) <= out_hip_ctrl_3;
    k_gbl(63 DOWNTO 48) <= out_hip_ctrl_4;
    k_dev(4 DOWNTO 0) <= out_hip_ctrl_5(15 DOWNTO 11);
    k_port(7 DOWNTO 0) <= out_hip_ctrl_5(7 DOWNTO 0);
    
    -- Register 6[6:0] for clk mux selection, bit [7] to select dbg_pipex1_rx or dbg_pipex1_tx signals, bit [8] to enable IEI logic
    k_clk_x8_sel_rtry <= (out_hip_ctrl_7(8 DOWNTO 7) & out_hip_ctrl_6(15 DOWNTO 14));
    k_clk_x8_sel_rcv1 <= (out_hip_ctrl_7(6 DOWNTO 5) & out_hip_ctrl_6(13 DOWNTO 12));
