    core_srst_int <= core_srst OR hard_reset;
    phy_srst_int <= phy_srst OR hard_reset;
    pld_srst_int <= pld_srst OR hard_reset;
    
    core_rstn_int <= core_rstn AND (NOT(hard_reset));
    core_npor_int <= core_npor AND (NOT(hard_reset));
    phy_rstn_int <= phy_rstn AND (NOT(hard_reset));
