	-- TSU/THOLD of pldclk
   VITAL_corecrst: PROCESS (pldclk_ipd, corecrst_ipd)
       variable Tviol_pldclk_corecrst : std_ulogic := '0';
       variable TimingData_pldclk_corecrst : VitalTimingDataType := VitalTimingDataInit;
   BEGIN
       IF (TimingChecksOn) THEN
           VitalSetupHoldCheck (
               Violation       => Tviol_pldclk_corecrst,
               TimingData      => TimingData_pldclk_corecrst,
               TestSignal      => corecrst_ipd,
               TestSignalName  => "corecrst",
               RefSignal       => pldclk_ipd,
               RefSignalName   => "PLDCLK",
               SetupHigh       => tsetup_corecrst_pldclk_noedge_posedge,
               SetupLow        => tsetup_corecrst_pldclk_noedge_posedge,
               HoldHigh        => thold_corecrst_pldclk_noedge_posedge,
               HoldLow         => thold_corecrst_pldclk_noedge_posedge,
               RefTransition   => '/',
               HeaderMsg       => InstancePath & "/arriaii_HSSI_PCIE_HIP",
               XOn             => XOnChecks,
               MsgOn           => MsgOnChecks
           );
       END IF;
   END PROCESS;

   VITAL_coresrst: PROCESS (pldclk_ipd, coresrst_ipd)
       variable Tviol_pldclk_coresrst : std_ulogic := '0';
       variable TimingData_pldclk_coresrst : VitalTimingDataType := VitalTimingDataInit;
   BEGIN
       IF (TimingChecksOn) THEN
