               RefSignalName   => "PLDCLK",
               SetupHigh       => tsetup_coresrst_pldclk_noedge_posedge,
               SetupLow        => tsetup_coresrst_pldclk_noedge_posedge,
               HoldHigh        => thold_coresrst_pldclk_noedge_posedge,
               HoldLow         => thold_coresrst_pldclk_noedge_posedge,
               RefTransition   => '/',
               HeaderMsg       => InstancePath & "/arriaii_HSSI_PCIE_HIP",
               XOn             => XOnChecks,
