   ----------------------
   --  Path Delay Section
   ----------------------
   -- TCO of pldclk
   VITAL_clrrxpath: PROCESS (pldclk_ipd, clrrxpath_tmp)
       variable CQDelayclrrxpath: TIME := 0 ns;
   BEGIN
       CQDelayclrrxpath := hssiSelectDelay (
           Paths => (0 => (pldclk_ipd'last_event, tpd_pldclk_clrrxpath_posedge, TRUE)));
       clrrxpath <= TRANSPORT clrrxpath_tmp AFTER CQDelayclrrxpath;
   END PROCESS;

